mapper.select:
SELECT l.id, l.user_id AS userId, l.question, l.hit_count AS hitCount, l.top_score AS topScore, l.mode, l.latency_ms AS latencyMs, l.created_at AS createdAt, u.username FROM kb_qa_log l LEFT JOIN sys_user u ON u.id = l.user_id
AND l.user_id = #{userId}
ORDER BY l.id DESC LIMIT #{limit}
